window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e919cf5fa73bd1c7"]={"versions": [{"id": "FIG-e919cf5fa73bd1c7", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-ECU-Konfigurationsmetamodells (ECUC) für das Basissoftware-Modul <code>Crc</code> (CRC Library) der Classic Platform. Dargestellt ist die Definitionsstruktur des Moduls mit Parametern und Enumeration-Literalen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Modul- und Container-Definitionen:</strong>\n<ul class=\"fig-list\"><li><code>Crc: EcucModuleDef</code> (Multiplizität: <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>).\n</li><li><code>CrcGeneral: EcucParamConfContainerDef</code>, per Komposition <code>+container</code> an <code>Crc</code> angebunden.\n</li></ul>\n</li><li><strong>Konfigurationsparameter (EcucEnumerationParamDef) in <code>CrcGeneral</code></strong> (jeweils mit Kardinalität <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>, angebunden über <code>+parameter</code>):\n<ul class=\"fig-list\"><li><code>Crc8Mode</code> mit Literalen (<code>+literal</code>, Typ <code>EcucEnumerationLiteralDef</code>): <code>CRC_8_TABLE</code>, <code>CRC_8_HARDWARE</code>, <code>CRC_8_RUNTIME</code>.\n</li><li><code>Crc8H2FMode</code> mit Literalen: <code>CRC_8H2F_TABLE</code>, <code>CRC_8H2F_HARDWARE</code>, <code>CRC_8H2F_RUNTIME</code>.\n</li><li><code>Crc16Mode</code> mit Literalen: <code>CRC_16_TABLE</code>, <code>CRC_16_RUNTIME</code>, <code>CRC_16_HARDWARE</code>.\n</li><li><code>Crc16ARCMode</code> mit Literalen: <code>CRC_16_ARC_TABLE</code>, <code>CRC_16_ARC_RUNTIME</code>, <code>CRC_16_ARC_HARDWARE</code>.\n</li><li><code>Crc32Mode</code> mit Literalen: <code>CRC_32_TABLE</code>, <code>CRC_32_RUNTIME</code>, <code>CRC_32_HARDWARE</code>.\n</li><li><code>Crc32P4Mode</code> mit Literalen: <code>CRC_32P4_HARDWARE</code>, <code>CRC_32P4_RUNTIME</code>, <code>CRC_32P4_TABLE</code>.\n</li><li><code>Crc64Mode</code> mit Literalen: <code>CRC_64_TABLE</code>, <code>CRC_64_RUNTIME</code>, <code>CRC_64_HARDWARE</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Deklarationsmodell ohne Laufzeit- oder Sequenzverhalten. Die Konfigurationsparameter bestimmen zur Generierungszeit die Berechnungsstrategie (tabellenbasiert, hardwarebeschleunigt oder zur Laufzeit berechnet) der jeweiligen CRC-Routinen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Metamodell-Definition für die Konfiguration des Moduls Crc. Die Enumerationswerte legen verbindlich fest, welche Ausführungsmodi je CRC-Algorithmus (8-Bit, 8-Bit H2F, 16-Bit, 16-Bit ARC, 32-Bit, 32-Bit P4 und 64-Bit) im BSW-Generator unterstützt bzw. konfiguriert werden können. Die Multiplizität 0..1 je Parameter erlaubt die selektive Aktivierung bzw. Konfiguration der Algorithmen.</p>"}, {"id": "FIG-d7e7fe523ffabedc", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-ECU-Konfigurationsmetamodells (ECUC) für das Basissoftware-Modul <code>Crc</code> (CRC Library) der Classic Platform. Dargestellt ist die Definitionsstruktur des Moduls mit Parametern und Enumeration-Literalen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Modul- und Container-Definitionen:</strong>\n<ul class=\"fig-list\"><li><code>Crc: EcucModuleDef</code> (Multiplizität: <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>).\n</li><li><code>CrcGeneral: EcucParamConfContainerDef</code>, per Komposition <code>+container</code> an <code>Crc</code> angebunden.\n</li></ul>\n</li><li><strong>Konfigurationsparameter (EcucEnumerationParamDef) in <code>CrcGeneral</code></strong> (jeweils mit Kardinalität <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>, angebunden über <code>+parameter</code>):\n<ul class=\"fig-list\"><li><code>Crc8Mode</code> mit Literalen (<code>+literal</code>, Typ <code>EcucEnumerationLiteralDef</code>): <code>CRC_8_TABLE</code>, <code>CRC_8_HARDWARE</code>, <code>CRC_8_RUNTIME</code>.\n</li><li><code>Crc8H2FMode</code> mit Literalen: <code>CRC_8H2F_TABLE</code>, <code>CRC_8H2F_HARDWARE</code>, <code>CRC_8H2F_RUNTIME</code>.\n</li><li><code>Crc16Mode</code> mit Literalen: <code>CRC_16_TABLE</code>, <code>CRC_16_RUNTIME</code>, <code>CRC_16_HARDWARE</code>.\n</li><li><code>Crc16ARCMode</code> mit Literalen: <code>CRC_16_ARC_TABLE</code>, <code>CRC_16_ARC_RUNTIME</code>, <code>CRC_16_ARC_HARDWARE</code>.\n</li><li><code>Crc32Mode</code> mit Literalen: <code>CRC_32_TABLE</code>, <code>CRC_32_RUNTIME</code>, <code>CRC_32_HARDWARE</code>.\n</li><li><code>Crc32P4Mode</code> mit Literalen: <code>CRC_32P4_HARDWARE</code>, <code>CRC_32P4_RUNTIME</code>, <code>CRC_32P4_TABLE</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Deklarationsmodell ohne Laufzeit- oder Sequenzverhalten. Die Konfigurationsparameter bestimmen zur Generierungszeit die Berechnungsstrategie (tabellenbasiert, hardwarebeschleunigt oder zur Laufzeit berechnet) der jeweiligen CRC-Routinen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Metamodell-Definition für die Konfiguration des Moduls Crc. Die Enumerationswerte legen verbindlich fest, welche Ausführungsmodi je CRC-Algorithmus (8-Bit, 8-Bit H2F, 16-Bit, 16-Bit ARC, 32-Bit und 32-Bit P4) im BSW-Generator unterstützt bzw. konfiguriert werden können. Die Multiplizität 0..1 je Parameter erlaubt die selektive Konfiguration der Algorithmen.</p>"}, {"id": "FIG-8781eb2a687b3b62", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-ECU-Konfigurationsmetamodells (ECUC) für das Basissoftware-Modul <code>Crc</code> (CRC Library) der Classic Platform. Dargestellt ist die Definitionsstruktur des Moduls mit Parametern und Enumeration-Literalen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Modul- und Container-Definitionen:</strong>\n<ul class=\"fig-list\"><li><code>Crc: EcucModuleDef</code> (Multiplizität: <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>).\n</li><li><code>CrcGeneral: EcucParamConfContainerDef</code>, per Komposition <code>+container</code> an <code>Crc</code> angebunden.\n</li></ul>\n</li><li><strong>Konfigurationsparameter (EcucEnumerationParamDef) in <code>CrcGeneral</code></strong> (jeweils mit Kardinalität <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>, angebunden über <code>+parameter</code>):\n<ul class=\"fig-list\"><li><code>Crc8Mode</code> mit Literalen (<code>+literal</code>, Typ <code>EcucEnumerationLiteralDef</code>): <code>CRC_8_TABLE</code>, <code>CRC_8_RUNTIME</code>.\n</li><li><code>Crc8H2FMode</code> mit Literalen: <code>CRC_8H2F_TABLE</code>, <code>CRC_8H2F_RUNTIME</code>.\n</li><li><code>Crc16Mode</code> mit Literalen: <code>CRC_16_TABLE</code>, <code>CRC_16_RUNTIME</code>.\n</li><li><code>Crc16ARCMode</code> mit Literalen: <code>CRC_16_ARC_TABLE</code>, <code>CRC_16_ARC_RUNTIME</code>.\n</li><li><code>Crc32Mode</code> mit Literalen: <code>CRC_32_TABLE</code>, <code>CRC_32_RUNTIME</code>.\n</li><li><code>Crc32P4Mode</code> mit Literalen: <code>CRC_32P4_RUNTIME</code>, <code>CRC_32P4_TABLE</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Deklarationsmodell ohne Laufzeit- oder Sequenzverhalten. Die Konfigurationsparameter bestimmen zur Generierungszeit die Berechnungsstrategie (tabellenbasiert, hardwarebeschleunigt oder zur Laufzeit berechnet) der jeweiligen CRC-Routinen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Metamodell-Definition für die Konfiguration des Moduls Crc. Die Enumerationswerte legen verbindlich fest, welche Ausführungsmodi je CRC-Algorithmus (8-Bit, 8-Bit H2F, 16-Bit, 16-Bit ARC, 32-Bit und 32-Bit P4) im BSW-Generator konfiguriert werden können; zur Auswahl stehen ausschließlich Tabellen- und Laufzeitberechnung (<code>TABLE</code> und <code>RUNTIME</code>). Die Multiplizität 0..1 je Parameter erlaubt die selektive Konfiguration der Algorithmen.</p>"}, {"id": "FIG-0aa515c56b03a188", "releases": ["R21-11", "R22-11", "EXTERN"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-ECU-Konfigurationsmetamodells (ECUC) für das Basissoftware-Modul <code>Crc</code> (CRC Library) der Classic Platform. Dargestellt ist die Definitionsstruktur des Moduls mit Parametern und Enumeration-Literalen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Modul- und Container-Definitionen:</strong>\n<ul class=\"fig-list\"><li><code>Crc: EcucModuleDef</code> (Multiplizität: <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>).\n</li><li><code>CrcGeneral: EcucParamConfContainerDef</code>, per Komposition <code>+container</code> an <code>Crc</code> angebunden.\n</li></ul>\n</li><li><strong>Konfigurationsparameter (EcucEnumerationParamDef) in <code>CrcGeneral</code></strong> (jeweils mit Kardinalität <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>, angebunden über <code>+parameter</code>):\n<ul class=\"fig-list\"><li><code>Crc8Mode</code> mit Literalen (<code>+literal</code>, Typ <code>EcucEnumerationLiteralDef</code>): <code>CRC_8_TABLE</code>, <code>CRC_8_HARDWARE</code>, <code>CRC_8_RUNTIME</code>.\n</li><li><code>Crc8H2FMode</code> mit Literalen: <code>CRC_8H2F_TABLE</code>, <code>CRC_8H2F_HARDWARE</code>, <code>CRC_8H2F_RUNTIME</code>.\n</li><li><code>Crc16Mode</code> mit Literalen: <code>CRC_16_TABLE</code>, <code>CRC_16_RUNTIME</code>, <code>CRC_16_HARDWARE</code>.\n</li><li><code>Crc16ARCMode</code> mit Literalen: <code>CRC_16_ARC_TABLE</code>, <code>CRC_16_ARC_RUNTIME</code>, <code>CRC_16_ARC_HARDWARE</code>.\n</li><li><code>Crc32Mode</code> mit Literalen: <code>CRC_32_TABLE</code>, <code>CRC_32_RUNTIME</code>, <code>CRC_32_HARDWARE</code>.\n</li><li><code>Crc32P4Mode</code> mit Literalen: <code>CRC_32P4_HARDWARE</code>, <code>CRC_32P4_RUNTIME</code>, <code>CRC_32P4_TABLE</code>.\n</li><li><code>Crc64Mode</code> mit Literalen: <code>CRC_64_TABLE</code>, <code>CRC_64_RUNTIME</code>, <code>CRC_64_HARDWARE</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Deklarationsmodell ohne Laufzeit- oder Sequenzverhalten. Die Konfigurationsparameter bestimmen zur Generierungszeit die Berechnungsstrategie (tabellenbasiert, hardwarebeschleunigt oder zur Laufzeit berechnet) der jeweiligen CRC-Routinen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Metamodell-Definition für die Konfiguration des Moduls Crc. Die Enumerationswerte legen verbindlich fest, welche Ausführungsmodi je CRC-Algorithmus (8-Bit, 8-Bit H2F, 16-Bit, 16-Bit ARC, 32-Bit, 32-Bit P4 und 64-Bit) im BSW-Generator unterstützt bzw. konfiguriert werden können. Die Multiplizität 0..1 je Parameter erlaubt die selektive Aktivierung bzw. Konfiguration der Algorithmen.</p>"}], "trans": [{"from": "FIG-0aa515c56b03a188", "to": "FIG-e919cf5fa73bd1c7", "fr": "R22-11", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-e919cf5fa73bd1c7", "to": "FIG-d7e7fe523ffabedc", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Entfall des Parameters <code>Crc64Mode: EcucEnumerationParamDef</code> inklusive seiner Literale <code>CRC_64_TABLE</code>, <code>CRC_64_RUNTIME</code> und <code>CRC_64_HARDWARE</code> aus dem Container <code>CrcGeneral</code>.\n</li></ul>"}, {"from": "FIG-d7e7fe523ffabedc", "to": "FIG-8781eb2a687b3b62", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Entfall des Literals <code>CRC_8_HARDWARE: EcucEnumerationLiteralDef</code> bei <code>Crc8Mode</code>.\n</li><li>Entfall des Literals <code>CRC_8H2F_HARDWARE: EcucEnumerationLiteralDef</code> bei <code>Crc8H2FMode</code>.\n</li><li>Entfall des Literals <code>CRC_16_HARDWARE: EcucEnumerationLiteralDef</code> bei <code>Crc16Mode</code>.\n</li><li>Entfall des Literals <code>CRC_16_ARC_HARDWARE: EcucEnumerationLiteralDef</code> bei <code>Crc16ARCMode</code>.\n</li><li>Entfall des Literals <code>CRC_32_HARDWARE: EcucEnumerationLiteralDef</code> bei <code>Crc32Mode</code>.\n</li><li>Entfall des Literals <code>CRC_32P4_HARDWARE: EcucEnumerationLiteralDef</code> bei <code>Crc32P4Mode</code>.\n</li></ul>"}]};
